package com.bank.controller.monitor;

import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;
import java.util.Set;

@Component
@Slf4j
public class IsrMonitor {

    // A partition sitting at ISR size 1 has NO safe failover target left.
    public void checkIsr(String partition, Set<String> isr, int minInsyncReplicas) {
        if (isr.size() < minInsyncReplicas) {
            log.error("{} ISR={} below min.insync.replicas={} — writes blocked, no safe leader spare",
                    partition, isr, minInsyncReplicas);
        } else if (isr.size() == minInsyncReplicas) {
            log.warn("{} ISR={} at the floor — one more failure stops writes", partition, isr);
        } else {
            log.info("{} ISR={} healthy", partition, isr);
        }
    }
}
