package com.bank.controller.demo;

import java.util.LinkedHashSet;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ControllerFailoverDemo {

    private static final Logger log = Logger.getLogger(ControllerFailoverDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        Controller controller = new Controller(/*uncleanElection*/ false);
        controller.registerBroker(new Broker("broker-1"));
        controller.registerBroker(new Broker("broker-2"));
        controller.registerBroker(new Broker("broker-3"));

        Partition p0 = new Partition("settlements-0", "broker-1");
        p0.isr.add("broker-1"); p0.isr.add("broker-2"); p0.isr.add("broker-3");
        p0.committedRecords = 10_000; // all ISR members hold these
        controller.track(p0);

        log.info("=== Leader broker-1 fails ===");
        controller.brokerFailed("broker-1", log);
        log.info("New leader of settlements-0 = " + p0.leader
                + ", committed records intact = " + p0.committedRecords
                + " (new leader was in-sync)");

        log.info("=== All remaining ISR fail (broker-2, broker-3) ===");
        controller.brokerFailed("broker-2", log);
        controller.brokerFailed("broker-3", log);
        log.info("Leader now = " + p0.leader + " (unclean election disabled -> wait, stay correct)");
    }
}

// ─── Would be in Broker.java in a real project ───
class Broker {
    final String name;
    boolean alive = true;
    Broker(String name) { this.name = name; }
}

// ─── Would be in Partition.java in a real project ───
class Partition {
    final String name;
    String leader;
    final Set<String> isr = new LinkedHashSet<>(); // includes the leader
    long committedRecords;
    Partition(String name, String leader) { this.name = name; this.leader = leader; }
}

// ─── Would be in Controller.java in a real project ───
class Controller {
    private final boolean uncleanElection;
    private final java.util.Map<String, Broker> brokers = new java.util.HashMap<>();
    private Partition tracked;

    Controller(boolean uncleanElection) { this.uncleanElection = uncleanElection; }

    void registerBroker(Broker b) { brokers.put(b.name, b); }
    void track(Partition p) { this.tracked = p; }

    // Controller detects a broker leaving and re-elects leaders from the ISR.
    void brokerFailed(String brokerName, Logger log) {
        Broker b = brokers.get(brokerName);
        if (b != null) b.alive = false;
        tracked.isr.remove(brokerName); // dead broker leaves the ISR

        if (brokerName.equals(tracked.leader)) {
            // Elect new leader ONLY from the surviving ISR (safe: holds all committed data).
            String newLeader = tracked.isr.stream().findFirst().orElse(null);
            if (newLeader != null) {
                tracked.leader = newLeader;
                log.info("Controller elected new leader " + newLeader + " from ISR " + tracked.isr
                        + " (no committed data lost)");
            } else if (uncleanElection) {
                tracked.leader = "STALE-REPLICA";
                log.severe("Unclean election: promoted out-of-sync replica — DATA LOSS possible");
            } else {
                tracked.leader = "NONE (waiting)";
                log.warning("No in-sync replica available; unclean election disabled -> "
                        + "partition UNAVAILABLE but correct, waiting for an ISR member to return");
            }
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
